    step1Text: "ज़ुनारा पर हर ग्रहीय स्थिति की गणना ओपन-सोर्स astronomy-engine लाइब्रेरी का उपयोग करके खगोलीय सिद्धांत से की जाती है, जो ग्रहीय गति के प्रसिद्ध VSOP87 विश्लेषणात्मक सिद्धांत के साथ-साथ पूर्वगमन (precession), कंपन (nutation) और विपथन (aberration) के लिए IAU मॉडल लागू करती है। ये वही श्रेणी के मॉडल हैं जो प्रकाशित पंचांगों में उपयोग होते हैं। हम कभी भी किसी ग्रहीय स्थिति का आविष्कार या अनुमान नहीं लगाते।",
    step1Title: "विधि",
    step2Text: "हमारे पूर्वानुमान एक पारदर्शी पाइपलाइन का पालन करते हैं: हम प्रत्येक दिन के लिए सूर्य, चंद्रमा और ग्रहों की सही स्थितियों और योगों की गणना करते हैं; उन्हें शास्त्रीय पश्चिमी उष्णकटिबंधीय ज्योतिष ढांचे और उसके स्वामित्व के माध्यम से व्याख्यायित करते हैं; फिर संरचित, मानव-लिखित संपादकीय अंशों को एक निश्चित (deterministic), पुनरुत्पादन योग्य तरीके से लिखते हैं। खगोल विज्ञान हमेशा सत्य का स्रोत है; लेखन उसे स्नेह के साथ प्रस्तुत करता है।",
    step2Title: "आंकड़ों से शब्दों तक",
    step3Text: "ज्योतिष चिंतन और मनोरंजन की प्रथा है, विज्ञान नहीं। यह चिंतन के लिए है और पेशेवर चिकित्सा, कानूनी या वित्तीय सलाह का विकल्प नहीं है। हम इसके बारे में पारदर्शी हैं, ताकि आप आकाश से खुले मन और ज़मीन से जुड़े मन दोनों के साथ जुड़ सकें।",
